WITH AccountStats AS (SELECT account_id, SUM(CASE WHEN txn_type = 'DEBIT' THEN 1 ELSE 0 END) AS debit_count, COUNT(*) AS transaction_count FROM transactions WHERE amount BETWEEN 2000 AND 2400 GROUP BY account_id) SELECT a.opened_date, a.customer_id, A.debit_count, A.transaction_count FROM accounts a LEFT JOIN AccountStats A ON a.id = A.account_id ORDER BY A.debit_count;
